from hashlib import sha256
from re import split as re_split

# This file contains specifications for the values of the fields returned by the /api/show endpoint
# It's just a simple look-up function that checks a dictionary for specific model values.

def construct_field_values(model: str) -> dict:
    # variations of the model name to use for the model's field values
    base_model_name = ""
    if ":" in model:
        base_model_name = re_split(r"[^A-Za-z]+", (model[:model.find(':')]), maxsplit=1)[0] # e.g., "gemma", "llama", "qwen" (no versions included!)
    else:
        base_model_name = re_split(r"[^A-Za-z]+", model, maxsplit=1)[0] # e.g., "gemma", "llama", "qwen" (no versions included!)
        model += ":latest" # if no parameters were given (for whatever reason), simply add "latest" as the version
    model_title_name = base_model_name.title() # e.g., "Gemma", "Llama", "Qwen"
    all_caps_model_name = base_model_name.upper() # e.g., "GEMMA", "LLAMA", "QWEN"

    # variations of the company name to use for the model's field values
    lowercase_company = _cached_companies.get(base_model_name, "google") # e.g., "google", "meta", "apache" - just default to "google"
    title_company = lowercase_company.title() # e.g., "Google", "Meta", "Apache"
    all_caps_company = lowercase_company.upper() # e.g., "GOOGLE", "META", "APACHE"

    # hashing the full model name, but with "-hash" to make it different from the hashes gotten from /api/tags and /api/ps (jnot sure why Ollama has different hashes for this endpoint, but sure)
    model_hash = sha256(f"{model}-hash".encode('utf-8')).hexdigest()

    field_values = cached_fields.copy()

    field_values["license"] = ((((((
        field_values["license"]
        ).replace("LOWERCASEMODELNAME", base_model_name)
        ).replace("UPPERCASEMODELNAME", model_title_name)
        ).replace("ALLCAPSMODELNAME", all_caps_model_name)
        ).replace("LOWERCASECOMPANYNAME", lowercase_company)
        ).replace("UPPERCASECOMPANYNAME", title_company)
        ).replace("ALLCAPSCOMPANYNAME", all_caps_company)

    field_values["modelfile"] = ((((((((
        field_values["modelfile"]
        ).replace("FULLMODELNAME", model)
        ).replace("MODELNAMESHAHASH", model_hash)
        ).replace("LOWERCASEMODELNAME", base_model_name)
        ).replace("UPPERCASEMODELNAME", model_title_name)
        ).replace("ALLCAPSMODELNAME", all_caps_model_name)
        ).replace("LOWERCASECOMPANYNAME", lowercase_company)
        ).replace("UPPERCASECOMPANYNAME", title_company)
        ).replace("ALLCAPSCOMPANYNAME", all_caps_company)

    return field_values


# DICTIONARY CONTAINING GENERALIZED FIELD VALUES TO BE USED FOR DIFFERENT MODELS
# They're generalized with valuse like "UPPERCASEMODELNAME" and "LOWERCASECOMPANYNAME", etc.,
# which are replaced with model-appropriate values in the "construct_field_values" function
# tensors are different for different models, but it's a super long list so it's (storage-wise) costly to cache them all for each model;
# instead, the ones for "gemma3:1b" are cached and used for all models.
# --------------------------------------------------
# Generalized with the following values (and what they correspond to):
# ---------- LICENSE FIELD GENERALIZATION ----------
# - LOWERCASEMODELNAME # "gemma"
# - UPPERCASEMODELNAME # "Gemma"
# - ALLCAPSMODELNAME # "GEMMA"
# - LOWERCASECOMPANYNAME # "google"
# - UPPERCASECOMPANYNAME # "Google"
# - ALLCAPSCOMPANYNAME # "GOOGLE"
# ---------- MODELFILE FIELD GENERALIZATION ----------
# - FULLMODELNAME # "gemma3:1b"
# - MODELNAMESHAHASH # <just some hash - DIFFERENT FROM THE ONE FROM /api/tags !>
# - LOWERCASEMODELNAME # "gemma"
# - UPPERCASEMODELNAME # "Gemma"
# - ALLCAPSMODELNAME # "GEMMA"
# - LOWERCASECOMPANYNAME # "google"
# - UPPERCASECOMPANYNAME # "Google"
# - ALLCAPSCOMPANYNAME # "GOOGLE"
